let currentAccessToken = null;

function setAccessToken(token, refreshToken) {
  currentAccessToken = token;
  if (token) {
    localStorage.setItem("mera_session", token);
    if (refreshToken) localStorage.setItem("mera_refresh", refreshToken);
  } else {
    localStorage.removeItem("mera_session");
    localStorage.removeItem("mera_refresh");
  }
}

async function sbFetch(path, options = {}, retries = 2) {
  for (let attempt = 0; attempt <= retries; attempt++) {
    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
        ...options,
        headers: {
          apikey: SUPABASE_KEY,
          Authorization: `Bearer ${currentAccessToken || SUPABASE_KEY}`,
          "Content-Type": "application/json",
          Prefer: options.method === "POST" ? "return=representation" : undefined,
          ...(options.headers || {}),
        },
      });
      if (!res.ok) {
        const text = await res.text();
        throw new Error(`Supabase error ${res.status}: ${text}`);
      }
      const text = await res.text();
      if (!text) return null;
      return JSON.parse(text);
    } catch (e) {
      // Only retry genuine network failures (fetch throwing before even reaching the server) —
      // not real errors like 400/403 from the database, which would just fail again identically.
      const isNetworkFailure = e instanceof TypeError;
      if (isNetworkFailure && attempt < retries) {
        await new Promise((r) => setTimeout(r, 400 * (attempt + 1)));
        continue;
      }
      throw e;
    }
  }
}

async function signIn(email, password) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=password`, {
    method: "POST",
    headers: { apikey: SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) {
    throw new Error(data.error_description || data.msg || "Login failed");
  }
  return data;
}

async function refreshSession(refreshToken) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`, {
    method: "POST",
    headers: { apikey: SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ refresh_token: refreshToken }),
  });
  if (!res.ok) return null;
  return res.json();
}

async function verifyToken(token) {
  const res = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
    headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${token}` },
  });
  if (!res.ok) return null;
  return res.json();
}

